[ExtensionOf(classStr(SalesCopying))]
public final class SalesCopyingGUP_Extension
{
    private EcoResAttribute origEcoResAttribute;
    private EcoResAttributeValue origEcoResAttributeValue;
    private RetailSalesTableInstanceValue origSalesTableInstanceValue;
    private EcoResValue origEcoResValue;
    private SalesTable origSalesTable;
    private RetailSalesTableInstanceValue salesTableInstanceValue;

}

Method.Source:
public void copyHeader()
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        this.copySalesOrderAttribute();
    }

    next copyHeader();
}

private void copySalesOrderAttribute()
{
    ttsbegin;

    if (tmpFrmVirtualHeader.RecId)
    {
        Common fromTrans = this.copyFromSourceTable(tmpFrmVirtualHeader);
        if (fromTrans.TableId == tableNum(CustInvoiceJour))
        {
            this.fillBuffer(fromTrans);

            this.clearEcoResAttributeValue();
            EcoResAttributeValue ecoResAttributeValue = this.copyEcoResAttributeValue(salesTable, salesTableInstanceValue);
        }
    }

    ttscommit;
}

private void clearEcoResAttributeValue()
{
    salesTableInstanceValue = RetailSalesTableInstanceValue::findBySalesTable(salesTable.SalesId, salesTable.DataAreaId);

    ttsbegin;
    EcoResAttributeValue ecoResAttributeValue;
    delete_from ecoResAttributeValue where ecoResAttributeValue.InstanceValue == salesTableInstanceValue.RecId;
    ttscommit;
}

private void fillBuffer(CustInvoiceJour _custInvoiceJour)
{
    origSalesTable = SalesTable::find(_custInvoiceJour.SalesId);
    origSalesTableInstanceValue = RetailSalesTableInstanceValue::findBySalesTable(origSalesTable.SalesId, origSalesTable.DataAreaId);
    // For now, only one attribute value is allowed for price tree.
    select firstonly origEcoResAttributeValue
        where origEcoResAttributeValue.InstanceValue == origSalesTableInstanceValue.RecId;
    if (origEcoResAttributeValue.RecId)
    {
        origEcoResAttribute = EcoResAttribute::find(origEcoResAttributeValue.Attribute);
        origEcoResValue = EcoResValue::find(origEcoResAttributeValue.Value);
    }

}

private EcoResAttributeValue copyEcoResAttributeValue(SalesTable _toSalesTable, RetailSalesTableInstanceValue _salesTableInstanceValue)
{
    ttsbegin;

    EcoResAttributeValue ecoResAttributeValue;
    ecoResAttributeValue.Value = origEcoResValue.pcDuplicate();
    ecoResAttributeValue.Attribute = origEcoResAttribute.RecId;
    ecoResAttributeValue.InstanceValue = _salesTableInstanceValue.RecId;
    ecoResAttributeValue.insert();

    ttscommit;
    return ecoResAttributeValue;
}
